        if not isinstance(other, Security):
            return NotImplemented
        return (
            super().__eq__(other)
            and self.scopes == other.scopes
        )

    def __hash__(self):
        return hash((super().__hash__(), tuple(self.scopes) if self.scopes else None))
```

