from dataclasses import dataclass
from typing import Optional, Sequence, Any, Callable, Union, Literal

@dataclass
class Depends:
    dependency: Optional[Any] = None
    use_cache: bool = True
    scope: Optional[str] = None

    def __eq__(self, other):
        if type(self) is not type(other):
            return NotImplemented
        return (
            self.dependency == other.dependency
            and self.use_cache == other.use_cache
            and self.scope == other.scope
        )

    def __hash__(self):
        return hash((self.dependency, self.use_cache, self.scope))

@dataclass
class Security(Depends):
    scopes: Optional[Sequence[str]] = None

    def __eq__(self, other):
        if type(self) is not type(other):
            return NotImplemented
        return (
            super().__eq__(other)
            and self.scopes == other.scopes
        )

    def __hash__(self):
        return hash((super().__hash__(), tuple(self.scopes) if self.scopes else None))

